import {esc} from './render.js';import {effectNames,pathLength} from './effects.js';import {worldPath,samples} from './core.js';
const num=(attr,key,label,value)=>`<div class="field"><label>${label}</label><input type="number" step="0.1" ${attr}="${key}" value="${Math.round((value??0)*10)/10}"></div>`;
const text=(attr,key,label,value,type='color')=>`<div class="field"><label>${label}</label><input type="${type}" ${attr}="${key}" value="${esc(value)}"></div>`;
const choose=(attr,key,label,value,choices)=>`<div class="field full"><label>${label}</label><select ${attr}="${key}">${choices.map(([v,n])=>`<option value="${v}" ${v===value?'selected':''}>${n}</option>`).join('')}</select></div>`;
export function smartControls(o,source){const a='data-prop';let fields='';if(o.type==='zipper')fields=choose(a,'zipType','Tipo',o.zipType||'jacket',[['jacket','Campera'],['jeans','Jean'],['invisible','Invisible']])+num(a,'pathLength','Largo',pathLength(samples(worldPath(source),48)))+num(a,'zipWidth','Ancho cierre',o.zipWidth)+num(a,'tapeWidth','Ancho cinta',o.tapeWidth??3)+num(a,'teeth','Tamaño diente',o.teeth)+num(a,'teethSpacing','Separación',o.teethSpacing)+num(a,'teethWidth','Ancho diente',o.teethWidth??o.zipWidth/2)+num(a,'sliderPercent','Deslizador %',(o.slider??.12)*100)+num(a,'openAmount','Apertura %',o.openAmount??0)+text(a,'tapeColor','Color cinta',o.tapeColor||o.stroke);
if(o.type==='cord')fields=choose(a,'cordStyle','Estilo',o.cordStyle||'flat',[['round','Redondo'],['wide','Ancho'],['flat','Plano'],['braided','Trenzado'],['elastic','Elástico']])+num(a,'pathLength','Largo',pathLength(samples(worldPath(source),48)))+num(a,'cordWidth','Ancho',o.cordWidth)+choose(a,'endType','Terminal',o.endType||'aglet',[['aglet','Puntera'],['knot','Nudo'],['none','Sin terminal']]);
if(['piping','binding','trim','elastic'].includes(o.type))fields=num(a,'effectWidth','Ancho',o.effectWidth??5)+num(a,'pathLength','Largo',pathLength(samples(worldPath(source),48)))+(o.type==='elastic'?num(a,'spacing','Separación',o.spacing):'');
if(['buttons','eyelets'].includes(o.type))fields=num(a,'count','Cantidad',o.count??5)+num(a,'itemSize','Radio',o.itemSize??5)+num(a,'pathLength','Largo fila',pathLength(samples(worldPath(source),48)));
if(o.type==='stitch')fields=choose(a,'stitchType','Estilo',o.stitchType||'single',[['single','Pespunte'],['long','Puntada larga'],['zigzag','Zigzag']])+choose(a,'rows','Filas',String(o.rows||1),[['1','Simple'],['2','Doble']])+num(a,'offset','Offset',o.offset)+num(a,'spacing','Separación',o.spacing)+num(a,'length','Largo puntada',o.length)+num(a,'rowGap','Distancia filas',o.rowGap??4)+num(a,'width','Grosor',o.width)+choose(a,'position','Lado',o.position,[['inside','Interior / izquierdo'],['outside','Exterior / derecho'],['centered','Centro']]);
return source?`<div class="prop-section"><h3>${effectNames[o.type]||'Efecto'} · Procedural</h3><div class="fields">${fields}</div><p>Los detalles se regeneran con la geometría. Su tamaño se mantiene al cambiar el largo.</p><div class="prop-buttons"><button data-action="selectSource">Editar trazado</button><button data-action="reverse">Invertir</button><button data-action="freeze">A vectores</button></div></div>`:'';}
export function modifierControls(o){if(o.type!=='path')return '';let s='<div class="prop-section"><h3>MODIFICADORES</h3>';for(const m of o.modifiers||[]){const attr=`data-mod="${m.id}" data-param`,a=attr;let fields='';if(m.type==='bend')fields=num(a,'amount','Curvatura (-100 a 100)',m.amount);else if(m.type==='rib')fields=choose(a,'direction','Dirección',m.direction,[['vertical','Vertical'],['horizontal','Horizontal'],['follow','Seguir forma'],['edge','Perpendicular al borde']])+num(a,'spacing','Separación',m.spacing)+num(a,'thickness','Grosor',m.thickness)+num(a,'inset','Margen',m.inset)+num(a,'density','Densidad',m.density)+num(a,'angle','Ángulo °',m.angle||0)+text(a,'stroke','Color',m.stroke);
else if(m.type==='fabricFall')fields=num(a,'intensity','Intensidad',m.intensity)+num(a,'length','Zona desde ruedo',m.length)+num(a,'irregularity','Irregularidad (0–1)',m.irregularity)+num(a,'foldCount','Cantidad de pliegues',m.foldCount)+num(a,'thickness','Grosor interiores',m.thickness)+num(a,'seed','Semilla',m.seed);else if(m.type==='quilt')fields=choose(a,'pattern','Patrón',m.pattern,[['horizontal','Horizontal'],['vertical','Vertical'],['grid','Grilla'],['diamond','Rombos']])+num(a,'spacing','Separación',m.spacing)+num(a,'angle','Ángulo',m.angle)+num(a,'inset','Margen',m.inset);else if(m.type==='pleat')fields=choose(a,'pleatType','Tipo',m.pleatType,[['knife','Cuchillo'],['box','Tabla']])+num(a,'pleatWidth','Ancho',m.pleatWidth)+num(a,'depth','Profundidad',m.depth)+num(a,'count','Cantidad',m.count)+choose(a,'direction','Dirección',m.direction,[['vertical','Vertical'],['horizontal','Horizontal']]);else if(m.type==='distress')fields=num(a,'count','Cantidad',m.count)+num(a,'length','Largo',m.length)+num(a,'seed','Semilla',m.seed);else if(m.type==='raw')fields=num(a,'intensity','Intensidad',m.intensity??2)+num(a,'spacing','Separación',m.spacing)+num(a,'length','Largo fibra',m.length)+num(a,'randomness','Aleatoriedad',m.randomness??.5)+num(a,'seed','Semilla',m.seed??1);else if(['piping','binding','elastic'].includes(m.type))fields=num(a,'effectWidth','Ancho',m.effectWidth??5)+num(a,'spacing','Separación',m.spacing)+num(a,'thickness','Grosor',m.thickness)+text(a,'stroke','Color',m.stroke);
else fields=num(a,'offset','Offset',m.offset)+num(a,'spacing','Separación',m.spacing)+num(a,'length','Puntada',m.length)+num(a,'thickness','Grosor',m.thickness)+num(a,'rows','Filas',m.rows)+num(a,'rowGap','Distancia filas',m.rowGap??4);
s+=`<details class="modifier-card" data-modifier-card="${m.id}" open><summary class="modifier-head"><label><input type="checkbox" data-mod="${m.id}" data-param="enabled" ${m.enabled!==false?'checked':''}> ${effectNames[m.type]||m.type}${m.rows===2?' doble':''}</label><span>${m.type!=='bend'?`<button data-action="modUp:${m.id}" title="Subir efecto">↑</button><button data-action="modDown:${m.id}" title="Bajar efecto">↓</button>`:''}<button data-action="modRemove:${m.id}" title="Quitar modificador">×</button></span></summary><div class="fields">${fields}</div></details>`;}
s+='<div class="prop-buttons"><button data-action="addModifier">+ Modificador</button><button data-action="freeze">A vectores</button></div></div>';return s;}
export function advancedGeometry(o,tool,nodeIndices){if(o.type!=='path')return '';const node=nodeIndices.length?o.nodes[nodeIndices.at(-1)]:null;return `<div class="prop-section"><h3>GEOMETRÍA ${o.closed?'· Cerrada':'· Abierta'}</h3>${o.subpaths?.length?`<div class="fields">${choose('data-prop','contour','Contorno editable','0',[['0','Principal'],...o.subpaths.map((c,i)=>[String(i+1),'Contorno '+(i+2)])])}</div>`:''}${tool==='node'?`<div class="fields">${choose('data-prop','nodeKind','Tipo de nodo',node?.kind||'corner',[['corner','Esquina'],['smooth','Suave'],['symmetric','Simétrico']])}</div><p>Shift + clic: varios nodos. Tiradores con tangencia según el tipo.</p><div class="prop-buttons"><button data-action="joinNodes">Unir nodos</button><button data-action="split">Dividir</button><button data-action="breakHandles">Romper tiradores</button></div>`:''}<div class="prop-buttons"><button data-action="${o.closed?'openPath':'closePath'}">${o.closed?'Abrir':'Cerrar'}</button><button data-action="bend">Curvar</button><button data-action="offset">Offset</button><button data-action="outline">Contornear línea</button><button data-action="mirrorGeom">Espejo geometría</button><button data-action="breakSymmetry">Romper simetría</button></div></div>`;}
export const alignmentControls=()=>`<div class="prop-buttons">${[['left','Izquierda'],['cx','Centro X'],['right','Derecha'],['top','Arriba'],['cy','Centro Y'],['bottom','Abajo'],['dx','Distribuir X'],['dy','Distribuir Y']].map(([v,n])=>`<button data-action="align:${v}" title="${n}">${n}</button>`).join('')}</div>`;
export const vectorControls=()=>`<div class="prop-buttons">${[['union','Unión'],['subtract','Restar'],['intersect','Intersección'],['difference','Diferencia'],['join','Unir trazados']].map(([v,n])=>`<button data-action="boolean:${v}" title="${n} de los trazados seleccionados">${n}</button>`).join('')}</div>`;
export const multiControls=()=>`<div class="prop-section"><h3>ALINEAR / DISTRIBUIR</h3>${alignmentControls()}</div><div class="prop-section"><h3>OPERACIONES VECTORIALES</h3>${vectorControls()}<div class="prop-buttons"><button data-action="compound">Trazado compuesto</button><button data-action="regionsFromLines">Regiones</button><button data-action="commandPalette">Todas las acciones…</button></div></div>`;
